def mk_case(top_specs, ref_pat, ref_origin):
    g=[[0]*15 for _ in range(15)]
    for color, pat, (r0,c0) in top_specs:
        for i,row in enumerate(pat):
            for j,v in enumerate(row):
                if v: g[r0+i][c0+j]=color
    for i,row in enumerate(ref_pat):
        for j,v in enumerate(row):
            if v: g[ref_origin[0]+i][ref_origin[1]+j]=1
    g[5]=[5]*15
    return g
def pat(s): return [[int(x) for x in row] for row in s.split('/')]
def expected(ref_pat, ref_origin_out, sel, sel_pat, sel_origin_out):
    o=[[0]*15 for _ in range(9)]
    for i,row in enumerate(ref_pat):
        for j,v in enumerate(row):
            if v: o[ref_origin_out[0]+i][ref_origin_out[1]+j]=1
    for i,row in enumerate(sel_pat):
        for j,v in enumerate(row):
            if v: o[sel_origin_out[0]+i][sel_origin_out[1]+j]=sel
    return o
